def factorial(n):
    if n == 0:
        return 1
    result = 1
    for i in range(1, n + 1):
        result *= i
    return result

def remove_duplicates(lst):
    seen = []
    for x in lst:
        if x not in seen:
            seen.append(x)
    return seen

def average(lst):
    if not lst:
        return 0
    return sum(lst) / len(lst)

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def fibonacci(n):
    if n <= 0:
        return 0
    if n == 1:
        return 1
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

def count_words(s):
    if not s.strip():
        return 0
    return len(s.split())

def multiply_list(lst):
    result = 1
    for x in lst:
        result *= x
    return result

def starts_with_uppercase(s):
    if not s:
        return False
    return s[0].isupper()

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def is_numeric_string(s):
    if not s:
        return False
    return s.isdigit()

def lcm(a, b):
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x
    return a * b // gcd(a, b)
